import { writeFileSync, readFileSync } from 'node:fs';
import { test } from 'vitest';
import GBNF from 'gbnf';

test('generate differential output', () => {
  const cases: [string, string][] = JSON.parse(readFileSync('/tmp/cases.json', 'utf-8'));
  const results = cases.map(([grammar, initial]) => {
    try {
      const state = GBNF(grammar, initial);
      const rules = [...state].map(rule => (
        'value' in rule ? { type: rule.type, value: rule.value } : { type: rule.type }
      ));
      return { rules };
    } catch (err) {
      const e = err as Error;
      return { error: `${e.name}: ${e.message}` };
    }
  });
  writeFileSync('/tmp/out_ts.json', JSON.stringify(results, null, 1));
});

