import { expect, test } from 'vitest';
import GBNF, { RuleType, RuleChar, RuleEnd, GrammarParseError, InputParseError, Graph, ParseState } from 'gbnf';

test('public exports are available at runtime', () => {
  expect(RuleType.CHAR).toBe('char');
  expect(RuleType.CHAR_EXCLUDE).toBe('char_exclude');
  expect(RuleType.END).toBe('end');
  expect(RuleType.REF).toBe('ref');
  expect(new RuleChar([1]).type).toBe(RuleType.CHAR);
  expect(new RuleEnd().type).toBe(RuleType.END);
  expect(typeof GrammarParseError).toBe('function');
  expect(typeof InputParseError).toBe('function');
  expect(typeof Graph).toBe('function');
  expect(typeof ParseState).toBe('function');
});

test('parse state exposes size, grammar and instanceof-able errors', () => {
  const grammar = 'root ::= "foo" | "bar"';
  const state = GBNF(grammar);
  expect(state.grammar).toBe(grammar);
  expect(state.size).toBe(2);
  expect(state.add('f').size).toBe(1);
  expect(() => GBNF(grammar, 'z')).toThrow(InputParseError);
  expect(() => GBNF('root = "foo"')).toThrow(GrammarParseError);
  try {
    GBNF(grammar, 'z');
  } catch (err) {
    expect(err).toBeInstanceOf(InputParseError);
    expect(err).toBeInstanceOf(Error);
  }
});

test('graph printing renders the grammar graph', () => {
  const state = GBNF('root ::= "ab" | [c-e]');
  expect(state.grammar).toBeTruthy();
  const printed = (state as unknown as { ['__graph__']?: Graph });
  expect(printed).toBeTruthy();
});

