import { expect, test } from 'vitest';
import { Graph } from '../src/grammar-graph/graph.js';
import { buildRuleStack } from '../src/grammar-parser/build-rule-stack.js';
import { RulesBuilder } from '../src/rules-builder/index.js';

const buildGraph = (grammar: string) => {
  const { rules, symbolIds } = new RulesBuilder(grammar);
  return new Graph(grammar, rules.map(buildRuleStack), symbolIds.get('root') as number);
};

test('graph.print renders nodes', () => {
  const graph = buildGraph('root ::= "ab" | [c-e] | foo\nfoo ::= [^x] "\\n"');
  const printed = graph.print();
  expect(printed).toContain('->');
  expect(printed).toContain('[a]');
  expect(printed).toContain('[ce]');
  expect(printed).toContain('Ref(');
  expect(printed).toContain('end');
  expect(printed).toContain('\\n');
  expect(graph.print(undefined, true)).toContain('\x1b[');
});

